import 'package:cloud_firestore/cloud_firestore.dart';

class Hotel {
  final String id;
  final String name;
  final String location;
  final double price;
  final double rating;
  final String imageUrl;
  final int reviews;
  final String description;
  final List<String> galleryImages;

  const Hotel({
    required this.id,
    required this.name,
    required this.location,
    required this.price,
    required this.rating,
    required this.imageUrl,
    this.reviews = 0,
    this.description = "No description available",
    this.galleryImages = const [],
  });

  // Factory to convert Firestore document into Hotel object
  factory Hotel.fromFirestore(DocumentSnapshot doc) {
    final data = doc.data() as Map<String, dynamic>? ?? {};

    return Hotel(
      id: doc.id,
      name: data['name'] ?? '',
      location: data['location'] ?? '',
      price: (data['price'] ?? 0).toDouble(),
      rating: (data['rating'] ?? 0).toDouble(),
      imageUrl: data['imageUrl'] ?? '',
      reviews: data['reviews'] is int ? data['reviews'] : 0,
      description: data['description'] ?? "No description available",
      galleryImages: data['galleryImages'] != null
          ? List<String>.from(data['galleryImages'])
          : [],
    );
  }

  // Convert Hotel object to map (for saving to Firestore)
  Map<String, dynamic> toMap() {
    return {
      'name': name,
      'location': location,
      'price': price,
      'rating': rating,
      'imageUrl': imageUrl,
      'reviews': reviews,
      'description': description,
      'galleryImages': galleryImages,
    };
  }
}

